def partition(values, x):
    less = [v for v in values if v < x]                                    # collect all values strictly less than x, in original order
    geq = [v for v in values if v >= x]                                    # collect all values >= x, in original order
    return less + geq                                                       # less-than partition first, then greater-or-equal partition


