import java.util.*;

public class Main {
    List<Integer> partition(List<Integer> values, int x) {
        List<Integer> less = new ArrayList<>();
        List<Integer> geq = new ArrayList<>();
        for (int v : values) {
            if (v < x) less.add(v);                                                   // collect all values strictly less than x, in original order
            else geq.add(v);                                                          // collect all values >= x, in original order
        }
        less.addAll(geq);                                                              // less-than partition first, then greater-or-equal partition
        return less;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> values = Arrays.asList(1, 4, 3, 2, 5, 2);
        System.out.println(solution.partition(values, 3));
    }
}

