#include <bits/stdc++.h>
using namespace std;

vector<int> partition(vector<int>& values, int x) {
    vector<int> less, geq;
    for (int v : values) {
        if (v < x) less.push_back(v);                                                // collect all values strictly less than x, in original order
        else geq.push_back(v);                                                       // collect all values >= x, in original order
    }
    less.insert(less.end(), geq.begin(), geq.end());                                    // less-than partition first, then greater-or-equal partition
    return less;
}

int main() {
    vector<int> values = {1, 4, 3, 2, 5, 2};
    vector<int> result = partition(values, 3);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

