import java.util.*;

public class Main {
    ListNode partition(ListNode head, int x) {
        ListNode lessDummy = new ListNode(0);
        ListNode geqDummy = new ListNode(0);
        ListNode lessTail = lessDummy;
        ListNode geqTail = geqDummy;

        ListNode node = head;
        while (node != null) {
            if (node.val < x) {
                lessTail.next = node;                                                  // append this node to the "less than x" chain
                lessTail = node;
            } else {
                geqTail.next = node;                                                     // append this node to the "greater-or-equal x" chain
                geqTail = node;
            }
            node = node.next;
        }

        geqTail.next = null;                                                            // terminate the geq chain (it may hold a stale next pointer)
        lessTail.next = geqDummy.next;                                                    // join: less chain's tail connects to geq chain's head
        return lessDummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(4, new ListNode(3, new ListNode(2, new ListNode(5, new ListNode(2))))));
        ListNode result = solution.partition(head, 3);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

