#include <bits/stdc++.h>
using namespace std;

ListNode* partition(ListNode* head, int x) {
    ListNode lessDummy(0);
    ListNode geqDummy(0);
    ListNode* lessTail = &lessDummy;
    ListNode* geqTail = &geqDummy;

    ListNode* node = head;
    while (node) {
        if (node->val < x) {
            lessTail->next = node;                                                    // append this node to the "less than x" chain
            lessTail = node;
        } else {
            geqTail->next = node;                                                        // append this node to the "greater-or-equal x" chain
            geqTail = node;
        }
        node = node->next;
    }

    geqTail->next = nullptr;                                                            // terminate the geq chain (it may hold a stale next pointer)
    lessTail->next = geqDummy.next;                                                       // join: less chain's tail connects to geq chain's head
    return lessDummy.next;
}

int main() {
    ListNode* head = new ListNode(1, new ListNode(4, new ListNode(3, new ListNode(2, new ListNode(5, new ListNode(2))))));
    ListNode* result = partition(head, 3);
    while (result) { cout << result->val << " "; result = result->next; }
    cout << endl;
    return 0;
}
